summary={'covered_checks_passed':True,'full_pitch_coverage_passed':b['passed'],'PC_only':True,'startup':[],'playback':[],'ordinary_comparisons':b['ordinary_comparisons'],'unchanged_originals':unchanged,'limits':b['limitations'],'coverage_gap':'Restored-state corrected runs produce notes and matching context captures but no quantizer calls; nonempty arp coverage assertions fail.'}
